AUTHOR='define_robotics_data_contracts:L14-author';BATCH='W03-L14';SOURCE='2dcca11fda764949d36f6f174bd72ccc2a83c2863f522635e7afd8539d88f84c'
now=datetime.datetime.now(datetime.timezone.utc).isoformat();Q=[];C={};NOTES={};ISSUES=[]
def form(expression,variables,units,assumptions=None):return {'expression':expression,'variables':variables,'units':units,'assumptions':assumptions or []}
def note(p,text,exclude=None):NOTES[p]={'text':text,'exclude':exclude}
def issue(p,text):ISSUES.append({'physicalPage':p,'description':text,'status':'qualified_not_silently_repaired'})
def add(key,title,pages,stem,opts,why,steps=None,formulas=None,kind='conceptual',difficulty='medium',correct=(0,),assumptions=None,angle=None,trap=None,memory=None,prereq=None):
 n=len(Q)+1;qid=f'{BATCH}-Q{n:03d}';cid=f'{BATCH}-C-{key}';ids=[f'o{(j+n)%len(opts)+1}' for j in range(len(opts))];options=[{'id':ids[j],'text':o[0]} for j,o in enumerate(opts)];options.sort(key=lambda o:hashlib.sha256((qid+o['id']).encode()).hexdigest())
 citations=[]
 for p in pages:
  citations.append({'slideId':f'lectures-p{p:04d}','sourceId':'lectures','sourceSha256':SOURCE,'physicalPage':p,'kind':'figure' if kind=='diagram' else ('equation' if formulas else 'statement'),'locator':f'Lecture 14, physical PDF page {p}, printed slide {p-427}: '+title,'evidenceText':(R/f'sources/text/lectures/page-{p:04d}.txt').read_text().strip(),'role':'premise' if kind in ('numerical','derivation','scenario') else 'explicit','region':None})
 q={'id':qid,'version':1,'status':'draft','authorId':AUTHOR,'stem':stem,'selectionMode':'multi' if len(correct)>1 else 'single','type':kind,'difficulty':difficulty,'cognitiveSkill':'numerical' if kind=='numerical' else ('synthesis' if difficulty in ('hard','extremely_tricky') else ('recall' if kind in ('definition','match') else 'application' if kind in ('derivation','scenario') else 'conceptual')),'week':3,'lectureId':'L14','topic':'Lagrangian manipulator dynamics','subtopic':title,'tags':[key,'lagrangian-dynamics'],'conceptIds':[cid],'assumptions':assumptions or [],'options':options,'correctOptionIds':[ids[j] for j in correct],'citations':citations,'solution':{'justification':why,'optionExplanations':{ids[j]:o[1] for j,o in enumerate(opts)},'steps':steps or [],'formulas':formulas or [],'simpleExplanation':why,'memoryAid':memory,'misconceptions':[o[1] for j,o in enumerate(opts) if j not in correct],'examTraps':[trap] if trap else [],'prerequisiteConceptIds':prereq or []},'origin':'generated','reviewIds':[]};Q.append(q)
 if cid not in C:C[cid]={'id':cid,'title':title,'description':why,'slideIds':[],'questionIds':[],'status':'drafted','topic':q['topic'],'subtopic':title,'prerequisiteConceptIds':prereq or [],'examinationAngles':[]}
 c=C[cid];c['questionIds'].append(qid);c['slideIds']=sorted(set(c['slideIds']+[x['slideId'] for x in citations]));c['examinationAngles']=sorted(set(c['examinationAngles']+[angle or kind]));return cid

def save(frozen=False):
 slides={s['id']:s for s in map(json.loads,(R/'sources/page_maps/lectures.jsonl').read_text().splitlines())};oldpath=R/f'data/inspection-batches/{BATCH}.json';old={s['physicalPage']:s for s in json.loads(oldpath.read_text())['slides']} if oldpath.exists() else {};outslides=[]
 for p,info in sorted(NOTES.items()):
  s=copy.deepcopy(slides[f'lectures-p{p:04d}']);s['disposition']='excluded' if info['exclude'] else 'examinable';s['exclusionReason']=info['exclude'];s['conceptIds']=[c['id'] for c in C.values() if s['id'] in c['slideIds']];s['visualInspection']={'status':'complete','inspectorId':AUTHOR,'inspectedAt':old.get(p,{}).get('visualInspection',{}).get('inspectedAt',now),'method':'rendered_page','notes':info['text']+' Actual 1800×1013 rendered pixels were viewed; not an extraction-only inspection.','previewSha256':hashlib.sha256((R/s['previewPath']).read_bytes()).hexdigest(),'dimensions':[1800,1013]};outslides.append(s)
 batch={'schemaVersion':'1.0.0','batchId':BATCH,'authorId':AUTHOR,'questions':Q,'concepts':list(C.values()),'sourceIssues':ISSUES,'coverageNote':('Author batch frozen for separate independent review; no claim of verified or exhaustive coverage.' if frozen else 'Incremental source-inspected draft; unfinished pages/angles and independent review remain.')}
 for typ,records in [('question',Q),('concept',C.values()),('slide',outslides)]:
  sch=json.loads((R/f'data/schema.{typ}.json').read_text());errors=[e for r in records for e in schema_errors(r,sch)];assert not errors,(typ,errors)
 for rel,obj in [(f'data/question-batches/{BATCH}.json',batch),(f'data/inspection-batches/{BATCH}.json',{'batchId':BATCH,'slides':outslides})]:(R/rel).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
 packet=[{**{k:q[k] for k in ['id','version','stem','selectionMode','type','difficulty','options','assumptions']},'questionSha256':question_hash(q),'citations':[{k:v for k,v in c.items() if k!='evidenceText'} for c in q['citations']]} for q in Q];(R/f'audits/blind-{BATCH}.json').write_text(json.dumps(packet,ensure_ascii=False,indent=2)+'\n')
 hashes={'batchId':BATCH,'frozen':frozen,'questions':[{'id':q['id'],'version':q['version'],'questionSha256':question_hash(q)} for q in Q],'batchSha256':hashlib.sha256((R/f'data/question-batches/{BATCH}.json').read_bytes()).hexdigest(),'blindPacketSha256':hashlib.sha256((R/f'audits/blind-{BATCH}.json').read_bytes()).hexdigest()};(R/f'audits/{BATCH}-question-hashes.json').write_text(json.dumps(hashes,indent=2)+'\n')
 (R/'docs/handoffs/L14-author.md').write_text(f'# L14 authoring recovery\n\nOwner: {AUTHOR}. Physical pages 428–449, Week3. Persisted {len(outslides)} actual page inspections, {len(C)} concept records and {len(Q)} draft questions. Frozen for independent review: {frozen}.\n\nAuthor source: scripts/author_W03_L14.py. Draft batch: data/question-batches/W03-L14.json. Inspection ledger: data/inspection-batches/W03-L14.json. Answer-free packet: audits/blind-W03-L14.json, citation evidenceText omitted. Hash manifest: audits/W03-L14-question-hashes.json.\n\nNo self-approval, canonical bank edits or Git actions. Continue remaining source observations, meaningful angles and independent-method numeric checks before final freeze. All source conventions and ambiguities stay explicit.\n')
 print(json.dumps({'questions':len(Q),'concepts':len(C),'inspected':len(NOTES),'frozen':frozen,**{k:hashes[k] for k in ['batchSha256','blindPacketSha256']}}))

note(428,'Printed 1 title identifies Lecture 14, Lagrangian Formulation of Manipulator Dynamics, lecturer and institute.','Title and branding only; no new technical proposition.')
note(429,'Printed 2 learning objective is analytical energy-based solution of manipulator dynamics.','Learning objective only; technical content follows.')
note(430,'Printed 3 contents list introduction, basics, dynamic equations, single-DOF and two-DOF examples.','Outline only; individual technical topics appear later.')
note(431,'Printed 4 two-column comparison: linkwise force/torque balance and recursive real-time Newton–Euler; scalar system energies and generalized-coordinate analytical Lagrangian formulation. Both give the same equations for the same model. Constraint-force treatment and AI/model-based-control motivation are stated qualitatively, not as performance guarantees.')
note(432,'Printed 5 kinetic-energy definition and work to/from rest. Translational K=1/2 M V² and fixed-axis rotational K=1/2 I omega², with speed magnitude and inertia about the rotation axis. No figure hidden in the empty lower-right box.')
note(433,'Printed 6 potential energy is force work from current r to reference r0: integral lower bound r, upper r0. Total E=K+U. Definition requires conservative position-dependent force for a single-valued potential; do not reverse the integral limits or confuse E with L.')
issue(433,'The slide does not explicitly state the conservative-force/path-independence condition for U(r). Questions using the force integral state that condition instead of treating an arbitrary force as admitting a position potential.')
note(434,'Printed 7 defines L=K−U, generalized coordinates and forces. Euler–Lagrange second numerator visibly uses dL with partial denominator, unlike consistent partial notation on page437. Names Rayleigh potential for dissipative forces and states inability to handle gyroscopic/circulatory forces; preserve as a restricted-source claim, not a universal theorem.')
note(435,'Printed 8 link kinetic energy is COM translation plus COM spin quadratic form, with arrows to each term; sum over all links. Angular velocity and inertia must share a coordinate basis; use COM inertia rather than double-counting joint-axis inertia.')
note(436,'Printed 9 u_i=−m_i g0^T pCi0+u_ref_i. Both gravity and COM position are base-frame 3-vectors; sum link energies. Reference constant is selected to place minimum at zero where an attainable finite minimum exists. Potential depends on joint positions through COM geometry.')
note(437,'Printed 10 scalar L and vector Euler–Lagrange equation. Substituting k−u gives +partial u/partial Theta. Calls tau an n×1 torque vector, which must be interpreted as generalized efforts for mixed prismatic joints introduced next.')
note(438,'Printed 11 three-column coordinate table: revolute radians, prismatic metres, mixed entries. Minimal nonredundant coordinates; six DOFs need six independent generalized coordinates; qdot is time derivative, not Cartesian velocity in general.')
note(439,'Printed 12 single-DOF diagram has X right, Y downward, gravity downward, point mass at distance l and torsional spring kt at pivot. Printed U=1/2 kt theta²−m g l sin theta fixes positive theta toward downward Y even though angle arc arrow is not fully decisive. K=1/2 m l² thetadot², datum y=0 and spring zero at theta=0.')
issue(434,'The blanket statement that gyroscopic and non-potential forces cannot be handled is not established as a universal result by the displayed restricted energy formulation. Retain explicit slide attribution if examined; do not teach it as a general impossibility of all generalized-force formulations. The dL/partial q mixed numerator typography is clarified by consistent page437 notation.')
issue(437,'The torque-only label for tau applies to all-revolute coordinates. The next page includes prismatic coordinates, and the RP final equations explicitly include a force; mixed-coordinate questions distinguish N·m and N.')
issue(439,'The angle-arc arrow alone is not a sufficient sign convention. Questions state theta positive from +X toward downward +Y, consistent with the displayed gravitational potential −mgl sin(theta), and assume the torsional spring is undeflected at theta=0.')
note(440,'Printed 13 computes partial k/partial thetadot=m l² thetadot, its time derivative, partial k/partial theta=0 and partial u/partial theta=kt theta−mgl cos theta. Final equation equals zero although initial general equation equals tau; this final example assumes zero applied actuator torque.')
note(441,'Printed 14 Newton check: gravity moment mgl sin(90−theta), spring moment −kt theta and inertial moment ml² thetaddot. Diagram force mg points downward. The 90 denotes degrees; write pi/2 when theta is in radians. Same free-motion equation as Lagrange.')
note(442,'Printed 15 RP manipulator sketch places l1 from base axis to first COM and d2 from base axis to second COM, not simply exposed slider length. Both diagonal COM inertia tensors shown. Gravity arrow downward. Absolute angle reference is not explicitly drawn; subsequent U proportional sin theta1 determines the upward-height convention.')
note(443,'Printed 16 separates link1 COM translation and spin; link2 radial and tangential translational speed squares plus same theta1 spin. Total coefficient A=m1 l1²+Izz1+Izz2+m2 d2². No cross velocity term because radial and tangential directions are orthogonal. Link1 U has constant +m1 l1 g.')
note(444,'Printed 17 link2 reference uses maximum extension d2max, a fixed parameter, not instantaneous d2. Displays full total U and all three derivative vectors in coordinate order(theta1,d2). Small blue repeated K at right is cropped at page edge; full prior page443 formula is readable and authoritative for that repetition.')
note(445,'Printed 18 expands the total time derivative and visibly retains +2m2 d2 thetadot1 d2dot, the product-rule velocity coupling in the first generalized equation. Subtracts partial k/partial q, yielding the negative radial squared-rate term. Generalized RHS uses tau1,tau2.')
note(446,'Printed 19 final scalar torque and force equations, full matrix decomposition and labeled M,V,G. Correct upper equations use +m2 d2² in A. Lower standalone M_x line visibly has an underscore-like mark before m2 d2² instead of a clear plus, inconsistent with the upper equation and positive kinetic coefficient. tau2 is force, not torque; M diagonal does not remove velocity coupling.')
note(447,'Printed 20 summary says L=K−V using V for scalar potential, then immediately uses V(Theta,Thetadot) for the velocity-product generalized-force vector. Same symbol has context-dependent roles, not equal mathematical objects. Scalar energy formulation still requires specified applied generalized forces and model assumptions.')
note(448,'Printed 21 bibliography cites Craig2005 and Merzouki et al2013.','References only; no additional examinable technical content.')
note(449,'Printed 22 centered Thank You and course-footer logos.','Closing only; no technical proposition.')
issue(440,'The final equality to zero silently specializes the preceding equation with applied torque tau to the unforced case. Generated questions state tau=0 explicitly or retain tau on the right.')
issue(441,'The source writes sin(90−theta) without a degree mark while the spring coordinate normally uses radians. Use cos(theta), or write sin(pi/2−theta) for radians; numerical spring torque always uses theta in radians.')
issue(442,'The RP figure does not identify a horizontal reference axis. State theta1 measured from horizontal toward positive upward height, consistent with its positive g(m1 l1+m2 d2)sin(theta1) potential. This differs from the single-DOF downward-positive convention.')
issue(446,'In the lower standalone M_x display, the character between Izz2 and m2 d2² resembles an underscore rather than a plus. Earlier K, the upper scalar torque and the upper full matrix equation all have a clear plus. Derive M11 from the positive kinetic-energy coefficient and disclose the inconsistent lower typography.')
issue(447,'V denotes potential energy in the first summary line but a velocity-dependent generalized-force vector in the dynamic decomposition. Questions distinguish scalar U (or V_potential) from vector V_velocity and do not conflate them.')

# First source-supported question slice.
ENERGY=form('K=1/2 m vCᵀvC+1/2 omegaᵀ I_C omega; K_total=sum_i K_i',{'K,K_total':'link and system kinetic energy','m':'link mass','vC':'COM velocity in an inertial reference','omega':'link angular velocity','I_C':'inertia tensor about COM, in the same component basis as omega'},{'K,K_total':'J','m':'kg','vC':'m/s','omega':'rad/s','I_C':'kg·m²'},['Rigid links; pair omega and I_C in one basis.'])
EL=form('L(q,qdot)=K(q,qdot)−U(q); Q_i=d/dt(partial L/partial qdot_i)−partial L/partial q_i',{'L':'scalar Lagrangian','K':'total kinetic energy','U':'potential energy','q_i':'independent generalized coordinate','qdot_i':'its time derivative','Q_i':'applied generalized actuator effort'},{'L,K,U':'J','q_i':'rad for revolute, m for prismatic','qdot_i':'rad/s or m/s','Q_i':'N·m for revolute, N for prismatic'},['Ideal constraints, chosen independent coordinates, conservative loads represented by U; other applied generalized efforts stated separately.'])
GRAV=form('U_i=−m_i g0ᵀpCi0+Uref_i; U_total=sum_i U_i',{'U_i,U_total':'link and total gravitational potential','m_i':'link mass','g0':'physical gravity vector in base coordinates','pCi0':'COM position in the same base coordinates','Uref_i':'constant energy datum'},{'U_i,U_total,Uref_i':'J','m_i':'kg','g0':'m/s²','pCi0':'m'},['Uniform gravity; reference constants are independent of q and qdot.'])
add('method-contrast','Comparing the two dynamics formulations',[431],'For the same rigid-body model and force conventions, which comparison matches the lecture?', [('Newton–Euler balances forces/moments link by link; Lagrange uses scalar system energies, and both give the same motion equations','Different derivations describe the same physical model.'),('Newton–Euler and Lagrange predict different motion even with identical assumptions','A change of formulation is not a change of physical model.'),('Lagrange requires every joint reaction as an independent unknown before energies can be formed','The independent-coordinate formulation avoids explicitly solving ideal constraint reactions.'),('Newton–Euler uses potential energy only, while Lagrange uses linkwise force balance only','This reverses and incompletely describes the two approaches.')], 'The slide contrasts computational organization, not competing laws of motion.',difficulty='easy',kind='match')
add('method-use','Choosing a formulation for the stated purpose',[431],'Which pairing is explicitly emphasized in the comparison slide?', [('Recursive Newton–Euler for real-time computation; Lagrangian formulation for systematic analytical models','This is the stated qualitative preference, not a universal speed guarantee.'),('Lagrangian models only for static robots; Newton–Euler only for moving robots','Both approaches derive dynamics.'),('Newton–Euler only for one DOF; Lagrange only for six DOFs','The methods are not restricted to these counts.'),('Newton–Euler for energy-datum selection; Lagrange only for contact-reaction recovery','Those are not the roles contrasted on the page.')], 'The lecture motivates Lagrangian analytical insight and model-based/AI dynamics learning while acknowledging recursive Newton–Euler computation.',difficulty='easy',assumptions=['This asks for the slide’s stated emphasis, not a hardware-independent runtime ranking.'])
add('ideal-constraints','What independent coordinates remove',[431,438],'For ideal joint constraints already incorporated in independent joint coordinates, what is the useful Lagrangian simplification?', [('One can derive actuator equations without treating every internal constraint reaction as an independent unknown','Allowed configurations are already represented by the coordinates.'),('Every physical reaction force becomes zero','Omitting reactions from the reduced equations does not make them physically vanish.'),('Every Cartesian coordinate becomes independently variable','The constraints still restrict motion.'),('Friction and nonconservative loads disappear automatically','Those loads require appropriate explicit modeling.')], 'Reduced coordinates account for the admissible motion, rather than claiming that joint reactions or losses do not exist.',assumptions=['Ideal constraints do no work along the allowed virtual motions.'])
add('kinetic-work','Kinetic energy and net work',[432],'A body’s speed doubles with its mass fixed. Under the stated translational kinetic-energy formula, what happens to K?', [('K becomes four times its original value','K is proportional to speed squared.'),('K doubles','That would be linear speed dependence.'),('K becomes eight times its original value','That incorrectly uses a cubic law.'),('K is unchanged because its mass is unchanged','Both mass and speed determine K.')], 'Doubling speed multiplies its square by four; starting or stopping requires the corresponding change in kinetic energy.',steps=['K_old=1/2 m v².','K_new=1/2 m(2v)²=4K_old.'],formulas=[ENERGY],difficulty='easy')
add('link-energy','Translation plus COM rotation',[432,435],'A rigid link has mass 2 kg, COM speed 3 m/s, COM axial inertia 0.5 kg·m² and angular speed 4 rad/s about that axis. What is its total kinetic energy?', [('13 J','Translation contributes 9 J and COM rotation contributes 4 J.'),('9 J','This omits COM spin energy.'),('4 J','This omits COM translational energy.'),('26 J','This omits the factor one-half in both quadratic terms.')], 'COM translation and spin are separate contributions and must both be retained.',steps=['K_translation=0.5×2×3²=9 J.','K_rotation=0.5×0.5×4²=4 J.','K=9+4=13 J.'],formulas=[ENERGY],kind='numerical')
add('energy-frame','Matching angular velocity and inertia coordinates',[435],'In omegaᵀ I_C omega, which requirement preserves a meaningful scalar spin energy?', [('I_C and omega must be expressed in the same coordinate basis, with I_C taken about the COM','The components must describe the same quadratic form.'),('Use any basis for I_C because its entries are scalars','Tensor entries change with the component basis.'),('Use joint-origin inertia while also keeping the full COM-translation term unchanged','That generally double-counts the translation embodied in the parallel-axis contribution.'),('Replace omega by COM linear velocity without changing I_C','That changes both meaning and units of the term.')], 'A scalar energy is coordinate-independent only when the components entering its formula are transformed consistently.',formulas=[ENERGY])
add('potential-integral','Potential reference and integral direction',[433],'For a conservative force f(r), the slide writes U(r)=integral from r to r0 of f·dr, with U(r0)=0. Which equivalent relation is correct?', [('U(r)=−integral from r0 to r of f·dr','Reversing integration limits changes the sign.'),('U(r)=integral from r0 to r of f·dr','This reverses the bounds without reversing sign.'),('U(r0) must equal the kinetic energy at r','The potential datum does not depend on speed.'),('U is determined by the speed along the return path','A conservative position potential is path-independent.')], 'The stored potential equals work released by the conservative force when returning to the chosen reference.',steps=['Use integral_a^b f·dr=−integral_b^a f·dr.','Apply a=r and b=r0.'],formulas=[form('U(r)=integral_r^r0 f·dr=−integral_r0^r f·dr',{'U':'potential relative to r0','r':'current position','r0':'reference position','f':'conservative force'},{'U':'J','r,r0':'m','f':'N'},['U(r0)=0; conservative force.'])],kind='derivation')
add('energy-versus-lagrangian','Total energy is not the Lagrangian',[433,434],'If K=12 J and U=5 J at one instant, which pair gives (total energy E, Lagrangian L)?', [('(17 J, 7 J)','E=K+U and L=K−U.'),('(7 J, 17 J)','This swaps E and L.'),('(17 J, −7 J)','This uses U−K for L.'),('(12 J, 5 J)','This mistakes the separate energies for their sum and difference.')], 'The plus sign defines total mechanical energy; the minus sign defines the Lagrangian.',steps=['E=12+5=17 J.','L=12−5=7 J.'],formulas=[form('E=K+U; L=K−U',{'E':'total mechanical energy','L':'Lagrangian','K':'kinetic energy','U':'potential energy'},{'E,L,K,U':'J'})],kind='numerical',difficulty='easy',memory='Energy adds; Lagrangian subtracts.')
add('lagrange-operator','Order of Euler–Lagrange differentiation',[434,437],'Which expression produces the applied generalized effort Q_i from L?', [('d/dt(partial L/partial qdot_i)−partial L/partial q_i','Differentiate with respect to the generalized velocity first, then in time.'),('d/dt(partial L/partial q_i)−partial L/partial qdot_i','This swaps the coordinate and velocity derivatives.'),('partial L/partial q_i−d/dt(partial L/partial qdot_i)','This reverses the generalized-effort sign.'),('partial L/partial qdot_i−partial L/partial q_i','This omits the time derivative of generalized momentum.')], 'The time derivative acts on the velocity derivative of L, not directly on L or on the coordinate derivative.',formulas=[EL],kind='definition',difficulty='easy')
add('potential-sign','The positive potential-gradient term',[437],'When U depends on q but not qdot, substituting L=K−U into Euler–Lagrange gives which energy form?', [('d/dt(K_qdot)−K_q+U_q=Q','The minus sign before L_q converts −U_q inside L_q to +U_q.'),('d/dt(K_qdot)−K_q−U_q=Q','This loses the double-negative sign.'),('d/dt(U_qdot)−U_q+K_q=Q','U_qdot is zero under the stated assumption and this is not the substitution.'),('d/dt(K_qdot)+K_q+U_q=Q','This reverses the K_q subtraction.')], 'Potential contributes its positive coordinate gradient on the actuator-effort side of the energy equation.',steps=['L_qdot=K_qdot because U_qdot=0.','L_q=K_q−U_q.','Subtract L_q to obtain −K_q+U_q.'],formulas=[EL],kind='derivation')
add('dissipation-caveat','The named dissipative extension',[434],'Which named addition does printed slide 7 mention when dissipative forces are present?', [('A Rayleigh potential function','This is the slide’s terminology for the dissipative extension.'),('A constant change of gravitational datum alone','A constant potential offset has no damping force gradient.'),('Replacing K−U by K+U for every system','That changes the definition rather than introducing dissipation.'),('Deleting generalized forces from the right-hand side','Omitting loads does not model their effects.')], 'This item reports the specific source statement. It does not claim that all damping laws admit a single Rayleigh function.',kind='definition',difficulty='easy',assumptions=['Source-attributed terminology only; no universal claim about arbitrary dissipative force laws.'])
add('limitation-attribution','Reading a source limitation without overgeneralizing',[434],'Which statement is explicitly printed as a limitation on slide 7, rather than established there as a theorem about every possible Lagrangian extension?', [('The shown approach cannot handle gyroscopic forces/moments or non-potential circulatory forces','That is the literal limitation claimed; its generality is not established by the slide.'),('Lagrangian equations cannot contain any actuator torque','The slide explicitly includes generalized forces or torques.'),('Lagrangian mechanics cannot use more than one generalized coordinate','The lecture proceeds to a two-DOF example.'),('Potential energy must always be zero','The defining expression explicitly includes U.')], 'Preserve attribution: this is a statement made by the limited presentation, not a universal impossibility result. Questions about a specific extended formulation would need its assumptions and equations.',kind='conceptual',assumptions=['Answer only what the identified slide states. Its blanket scope is recorded as a source issue.'])
add('gravity-vector','Sign of gravitational potential',[436],'With upward +Y, g0=(0,−10,0) m/s², COM position (2,3,0) m, m=2 kg and Uref=0, what is U?', [('60 J','−m g0·p=−2(−30)=60.'),('−60 J','This omits the leading minus in −m g0ᵀp.'),('40 J','This uses the horizontal coordinate rather than height.'),('30 J','This omits the mass multiplier.')], 'The vector formula gives increasing potential with upward height when physical gravity points downward.',steps=['g0·p=0×2−10×3+0=−30 m²/s².','U=−2×(−30)=60 J.'],formulas=[GRAV],kind='numerical')
add('potential-datum','Constant energy references do not alter effort',[436,437],'If a constant C independent of q and qdot is added to U, what changes in the Euler–Lagrange actuator equations?', [('Nothing; the derivatives of C vanish','The potential datum shifts but its gradients do not.'),('Every actuator effort increases by C','C has energy units and zero coordinate gradient.'),('The mass matrix increases by C times the identity','A potential constant changes no velocity derivatives.'),('Every gravity-compensation effort reverses sign','An additive constant does not reverse U_q.')], 'Only changes of potential with configuration affect the generalized force, not an arbitrary zero of energy.',steps=['Replace U by U+C.','partial C/partial q_i=0 and partial C/partial qdot_i=0.','All Euler–Lagrange terms are unchanged.'],formulas=[EL,GRAV],kind='derivation')
add('generalized-coordinates','Mixed coordinates and effort units',[437,438],'For q=(theta1,d2,theta3)ᵀ with two revolute joints and one prismatic joint, which units belong to the corresponding effort vector?', [('(N·m, N, N·m)','Rotational coordinates pair with torques; the displacement coordinate pairs with force.'),('(N·m, N·m, N·m)','The prismatic effort is a force, despite the generic tau symbol.'),('(N, N, N)','This treats rotational generalized efforts as translational forces.'),('(rad, m, rad)','These are coordinate units rather than effort units.')], 'Each coordinate’s effort is chosen so effort times its differential contributes work.',formulas=[EL],kind='match')
add('coordinate-minimality','Independent coordinates and generalized velocity',[438],'For a robot with six independent DOFs using the lecture’s minimal-coordinate convention, which statements are correct? Select all that apply.', [('Six independent generalized coordinates describe its configuration','The minimum-coordinate count equals the DOF count.'),('qdot consists of the time derivatives of those coordinates','It gives angular rates or displacement rates as appropriate.'),('Every component of qdot must have units of m/s','Revolute coordinates produce angular rates.'),('The robot needs six Cartesian coordinates for every link as independent generalized coordinates','That would introduce redundant constrained coordinates rather than the stated minimal set.')], 'Minimal joint coordinates remove redundant configuration variables; their time derivatives need not be Cartesian end-effector velocity.',correct=(0,1),kind='multiple_select')

SINGLE='Use the single-joint point-mass model: massless arm of length l>0, tip mass m>0, X right, Y downward, theta positive from +X toward +Y, physical gravity +g Y with g≥0, and a torsional spring undeflected at theta=0. theta in the spring law is in radians. Positive applied torque tau increases theta; no damping unless explicitly added.'
SENERGY=form('K=1/2 m l² thetadot²; U=1/2 kt theta²−m g l sin(theta)',{'K':'kinetic energy','U':'spring plus gravitational potential','m':'tip mass','l':'pivot-to-mass length','theta':'downward-positive joint angle from +X','thetadot':'joint angular rate','kt':'torsional spring stiffness','g':'positive gravity magnitude'},{'K,U':'J','m':'kg','l':'m','theta':'rad','thetadot':'rad/s','kt':'N·m/rad','g':'m/s²'},[SINGLE])
SDYN=form('m l² thetaddot+kt theta−m g l cos(theta)=tau',{'m':'tip mass','l':'pivot-to-mass length','thetaddot':'joint angular acceleration','kt':'torsional spring stiffness','theta':'downward-positive angle from horizontal','g':'gravity magnitude','tau':'externally applied actuator torque'},{'m':'kg','l':'m','thetaddot':'rad/s²','kt':'N·m/rad','theta':'rad','g':'m/s²','tau':'N·m'},[SINGLE,'The source’s final equality to zero is the special case tau=0.'])
add('single-angle','Geometry fixes the gravitational sign',[439],'In the single-joint example, take theta positive from rightward +X toward downward +Y. Which pair gives the tip’s downward coordinate y and gravitational potential relative to y=0?', [('y=l sin(theta), U_g=−mgl sin(theta)','Moving downward reduces gravitational potential.'),('y=l sin(theta), U_g=+mgl sin(theta)','This uses the upward-height sign despite downward-positive y.'),('y=l cos(theta), U_g=−mgl cos(theta)','That would measure theta from the vertical, not +X.'),('y=l sin(theta), U_g=−mgl cos(theta)','The potential would not equal −mg times the stated downward coordinate.')], 'The printed potential and axes determine the convention. Do not import the later RP example’s upward-height angle unchanged.',formulas=[SENERGY],kind='diagram',assumptions=[SINGLE])
add('spring-energy','Torsional spring energy and torque',[439,440],'For the undeflected-at-zero torsional spring, which pair gives stored energy U_s and its physical torque on the arm?', [('U_s=1/2 kt theta²; spring torque=−kt theta','Differentiating U_s and taking the restoring minus sign yields the torque.'),('U_s=kt theta²; spring torque=−kt theta','The stated torque integrates to one-half kt theta², not kt theta².'),('U_s=1/2 kt theta²; spring torque=+kt theta','This reverses the restoring direction.'),('U_s=1/2 kt theta; spring torque=−kt theta²','These are not an energy and its negative angle derivative.')], 'The potential-gradient contribution appears positively in the required actuator equation, while the spring’s physical restoring torque is its negative.',steps=['Differentiate U_s=1/2 kt theta² to get kt theta.','Physical spring torque is −partial U_s/partial theta=−kt theta.'],formulas=[SENERGY,SDYN],kind='derivation',assumptions=[SINGLE])
add('single-kinetic-partial','A coordinate-independent kinetic coefficient',[440],'Why is partial K/partial theta=0 for K=1/2 m l² thetadot² in this model?', [('m and l are constants and the partial derivative holds thetadot fixed','There is no explicit theta dependence in K.'),('The arm must be stationary whenever a partial derivative is taken','A nonzero thetadot is compatible with partial K/partial theta=0.'),('Every manipulator kinetic energy is independent of joint position','The later RP example depends on d2 through m2 d2².'),('The gravitational potential is zero at theta=0','Potential values do not determine the coordinate derivative of K.')], 'A partial derivative checks explicit dependence on one independent argument. It does not impose a zero velocity.',formulas=[SENERGY],assumptions=[SINGLE])
add('single-unforced','The zero right-hand side is an assumption',[439,440],'The example first writes the general applied torque tau, then ends with ml² thetaddot+kt theta−mgl cos(theta)=0. What is the consistent interpretation?', [('The final displayed motion equation specializes to zero externally applied actuator torque','Spring and gravity remain within the potential terms.'),('The actuator torque is always zero for every Lagrangian system','The general equation explicitly allows applied generalized effort.'),('Gravity must be zero because the right side is zero','The gravitational term remains on the left.'),('The spring torque and gravity torque each vanish separately','Only their net effect and inertia balance; neither need vanish alone.')], 'A homogeneous right-hand side means no separately applied actuator input, not absence of conservative forces.',formulas=[SDYN],assumptions=[SINGLE])
add('single-equation','Deriving the actuator equation',[439,440],'Using the displayed K and U, which equation retains a nonzero applied torque tau in the positive theta direction?', [('ml² thetaddot+kt theta−mgl cos(theta)=tau','It follows from the time derivative of kinetic momentum plus U_theta.'),('ml² thetaddot−kt theta−mgl cos(theta)=tau','This gives the spring the wrong potential-gradient sign.'),('ml² thetaddot+kt theta+mgl cos(theta)=tau','This changes the specified downward-positive gravity convention.'),('ml² thetaddot+kt theta−mgl sin(theta)=tau','The derivative of sin(theta) is cos(theta).')], 'Differentiate the energies before substituting: the spring gives kt theta and gravity gives −mgl cos(theta).',steps=['K_thetadot=ml² thetadot, hence its time derivative is ml² thetaddot.','K_theta=0.','U_theta=kt theta−mgl cos(theta).','Combine the terms and retain tau on the right.'],formulas=[SENERGY,SDYN],kind='derivation',assumptions=[SINGLE])
add('single-numerical','Computing applied torque with radians',[440],'Let m=2 kg, l=0.5 m, kt=3 N·m/rad, g=10 m/s², theta=pi/6 rad and thetaddot=4 rad/s². What applied torque tau is required?', [('2+pi/2−5√3 N·m, approximately −5.09 N·m','Inertia is 2, spring gradient pi/2, gravity gradient −5√3.'),('2+pi/2+5√3 N·m','This reverses the gravity-gradient sign.'),('pi/2−5√3 N·m','This omits the required acceleration torque.'),('2−pi/2−5√3 N·m','This reverses the spring-gradient sign.')], 'The three signed contributions are calculated separately; the spring uses the angle in radians.',steps=['ml²=2×0.5²=0.5 kg·m², so inertia torque=0.5×4=2 N·m.','kt theta=3×pi/6=pi/2 N·m.','mgl cos(theta)=2×10×0.5×√3/2=5√3 N·m.','tau=2+pi/2−5√3≈−5.09 N·m.'],formulas=[SDYN],kind='numerical',assumptions=[SINGLE,'Round only the final decimal to two places.'])
add('horizontal-release','Initial free acceleration at zero spring deflection',[440,441],'The arm is released from theta=0 with tau=0 and no damping. What is its instantaneous angular acceleration?', [('g/l in the positive downward direction','The spring torque is zero and ml² thetaddot=mgl.'),('Zero because the spring is undeflected','Gravity still has its maximum moment at the horizontal position.'),('−g/l','This reverses the defined positive angle direction.'),('g/(2l)','This inserts an unsupported factor of two in the inertia balance.')], 'Zero spring deflection does not imply mechanical equilibrium when gravity acts with a nonzero lever arm.',steps=['Set theta=0, cos(theta)=1 and tau=0.','ml² thetaddot=mgl.','Divide by ml² to obtain thetaddot=g/l.'],formulas=[SDYN],kind='derivation',assumptions=[SINGLE])
add('spring-equilibrium','Equilibrium of spring and gravity',[440,441],'For tau=0, which condition must a static equilibrium angle theta_e satisfy?', [('kt theta_e=mgl cos(theta_e)','Spring and gravity moments balance when angular acceleration is zero.'),('kt theta_e=mgl sin(theta_e)','This uses the wrong trigonometric lever arm.'),('theta_e=0 for every positive m,g,l','The horizontal undeflected spring cannot balance nonzero gravity torque.'),('kt=mgl regardless of theta_e','The actual balance depends on angle, not just parameter equality.')], 'Static equilibrium means zero net torque, not necessarily zero stored energy or zero individual torque.',steps=['Set thetaddot=0 and tau=0 in the equation.','Rearrange kt theta_e−mgl cos(theta_e)=0.'],formulas=[SDYN],kind='derivation',assumptions=[SINGLE])
add('newton-check','Matching the Newton moment equation',[441],'With theta in radians, which gravitational-moment expression matches the source’s sin(90−theta) geometric construction?', [('mgl sin(pi/2−theta)=mgl cos(theta)','The right-angle complement must use the same angular units.'),('mgl sin(90−theta) with the number 90 interpreted as radians','That mixes a degree complement with a radian coordinate.'),('mgl sin(theta)','That measures the complementary lever-arm angle incorrectly.'),('−mgl cos(theta) as the physical gravity torque in the positive downward direction','Physical gravity assists positive theta near horizontal; the negative term occurs after rearranging the actuator equation.')], 'The Newton derivation and the Lagrangian derivation agree only when the coordinate direction and angular units are kept consistent.',steps=['A right angle is pi/2 radians.','sin(pi/2−theta)=cos(theta).','Physical net torque is mgl cos(theta)−kt theta.'],formulas=[SDYN],kind='diagram',assumptions=[SINGLE])
add('spring-angle-units','Degrees in trigonometry versus radians in a spring law',[439,440],'For kt=4 N·m/rad and theta=90°, what is the magnitude of the spring torque?', [('2pi N·m','Convert 90° to pi/2 rad before multiplying by 4.'),('360 N·m','This multiplies stiffness per radian by the number of degrees.'),('4 N·m','This treats 90° as one radian.'),('Zero','The gravitational moment is zero there, but the spring deflection is not zero.')], 'A trigonometric calculator may accept degrees, but the stiffness unit explicitly requires radians.',steps=['90°=pi/2 rad.','|torque_s|=kt|theta|=4×pi/2=2pi N·m.'],formulas=[SENERGY],kind='numerical',assumptions=[SINGLE])
add('energy-power','Conservative energy and applied power',[439,440],'For E=K+U in the stated undamped single-joint model, what relation follows from the driven equation?', [('dE/dt=tau thetadot','Multiply the equation by thetadot and identify the derivatives of K and U.'),('dE/dt=0 even when tau thetadot is nonzero','An actuator can supply or remove mechanical energy.'),('dE/dt=tau thetaddot','Torque times angular acceleration is not the mechanical-power pairing.'),('dE/dt=−tau thetadot for the same applied-torque convention','This reverses the specified input-power sign.')], 'Conservative spring and gravity terms exchange kinetic and potential energy. Applied torque changes the total through its power.',steps=['dK/dt=ml² thetaddot thetadot.','dU/dt=(kt theta−mgl cos(theta)) thetadot.','Add and use the motion equation to obtain tau thetadot.'],formulas=[SENERGY,SDYN,form('dE/dt=tau thetadot',{'E':'total mechanical energy K+U','tau':'applied actuator torque','thetadot':'angular rate'},{'E':'J','tau':'N·m','thetadot':'rad/s','dE/dt':'W'},['Undamped conservative single-joint model.'])],kind='derivation',assumptions=[SINGLE])
add('zero-gravity-limit','Zero-gravity torsional oscillation',[440],'With g=0, tau=0 and kt>0, which angular natural frequency follows from ml² thetaddot+kt theta=0?', [('sqrt(kt/(ml²))','Divide by the rotational inertia ml² to obtain the coefficient of theta.'),('sqrt(ml²/kt)','This is the reciprocal quantity, with time rather than inverse-time units.'),('sqrt(kt/m)','This omits the squared moment arm in rotational inertia.'),('kt/(ml²)','This is the squared natural frequency, not the frequency.')], 'This is a derived limiting case of the printed motion equation, not an additional force model.',steps=['Divide by ml²: thetaddot+[kt/(ml²)]theta=0.','Compare with the supplied oscillator form thetaddot+omega_n² theta=0.','omega_n=sqrt(kt/(ml²)).'],formulas=[SDYN,form('omega_n=sqrt(kt/(ml²))',{'omega_n':'undamped angular natural frequency','kt':'torsional stiffness','m':'tip mass','l':'arm length'},{'omega_n':'rad/s','kt':'N·m/rad','m':'kg','l':'m'},['g=tau=0 and kt,m,l positive.'])],kind='derivation',assumptions=[SINGLE,'Use the standard oscillator form thetaddot+omega_n² theta=0, explicitly supplied here.'])

RP='Use the lecture’s rigid planar RP model, q=(theta1,d2): theta1 measured counterclockwise from horizontal toward upward height; d2 is the base-axis-to-link2-COM distance, positive outward. Gravity is downward with magnitude g. Masses m1,m2, first COM radius l1 and COM inertias Izz1,Izz2 are constant; m1,m2,l1>0. Positive effort Q=(tau1,F2) increases theta1 and d2. No friction, applied terminal load or extra spring. d2max is a fixed maximum extension, not d2(t).'
RPE=form('A(d2)=m1 l1²+Izz1+Izz2+m2 d2²; K=1/2 A(d2) thetadot1²+1/2 m2 d2dot²; U=g(m1 l1+m2 d2)sin(theta1)+m1 l1 g+m2 g d2max',{'A':'rotational kinetic coefficient about joint1','K':'total kinetic energy','U':'total potential energy','m1,m2':'link masses','l1':'joint1-axis to link1-COM distance','d2':'joint1-axis to link2-COM distance','Izz1,Izz2':'link COM inertias about parallel out-of-plane axes','theta1':'upward-positive revolute angle','thetadot1':'angular rate','d2dot':'radial COM rate','d2max':'fixed maximum radial extension','g':'gravity magnitude'},{'A,Izz1,Izz2':'kg·m²','K,U':'J','m1,m2':'kg','l1,d2,d2max':'m','theta1':'rad','thetadot1':'rad/s','d2dot':'m/s','g':'m/s²'},[RP])
RPD=form('tau1=A(d2) thetaddot1+2m2 d2 thetadot1 d2dot+g(m1 l1+m2 d2)cos(theta1); F2=m2 d2ddot−m2 d2 thetadot1²+m2 g sin(theta1)',{'tau1':'applied revolute actuator torque','F2':'applied outward prismatic force (source symbol tau2)','A':'m1 l1²+Izz1+Izz2+m2 d2²','m1,m2':'link masses','l1':'first COM radius','d2':'second COM radius','theta1':'upward-positive revolute angle','thetadot1,thetaddot1':'angular rate and acceleration','d2dot,d2ddot':'radial speed and acceleration','g':'gravity magnitude'},{'tau1':'N·m','F2':'N','A':'kg·m²','m1,m2':'kg','l1,d2':'m','theta1':'rad','thetadot1':'rad/s','thetaddot1':'rad/s²','d2dot':'m/s','d2ddot':'m/s²','g':'m/s²'},[RP])
RPM=form('Q=M(q) qddot+V(q,qdot)+G(q); M=diag(A,m2); V=[2m2 d2 thetadot1 d2dot,−m2 d2 thetadot1²]ᵀ; G=[g(m1 l1+m2 d2)cos(theta1),m2 g sin(theta1)]ᵀ',{'Q':'[tau1,F2]ᵀ applied mixed generalized efforts','q':'[theta1,d2]ᵀ','qdot,qddot':'coordinate rates and accelerations','M':'mixed-coordinate mass matrix','A':'m1 l1²+Izz1+Izz2+m2 d2²','V':'velocity-product effort vector, not potential energy','G':'gravity-gradient effort vector','m1,m2':'link masses','l1,d2':'COM radii','theta1':'revolute angle','thetadot1':'angular rate','d2dot':'radial speed','g':'gravity magnitude'},{'Q,V,G component1':'N·m','Q,V,G component2':'N','M11,A':'kg·m²','M22,m1,m2':'kg','l1,d2':'m','theta1':'rad','thetadot1':'rad/s','d2dot':'m/s','g':'m/s²'},[RP])
add('rp-geometry','What the RP distance d2 measures',[442],'In the RP figure, what is d2 as used in the kinetic and potential energies?', [('Distance from the first joint axis to the center of mass of link2','The diagram and accompanying text specify the full COM radius.'),('Only the exposed slider length beyond the end of link1','That length need not equal the base-to-COM distance.'),('Distance between the two link centers of mass','The lower dimension line begins at the first joint axis.'),('Distance from the second COM to the tool tip','That is not the marked dimension.')], 'The correct radius is needed in both rotational speed d2 thetadot1 and gravity height d2 sin(theta1).',kind='diagram',assumptions=[RP])
add('rp-inertia-component','Why only Izz appears',[442,443],'The given COM inertia tensors are diagonal and motion rotates about the out-of-plane z axis. Which COM rotational-inertia terms enter K?', [('Izz1 and Izz2','omega=(0,0,thetadot1), so the quadratic form selects the z entries.'),('Ixx1 and Ixx2 only','Those would describe spin about the x axes.'),('The sums Ixx+Iyy+Izz for both links','The trace is not the inertia about the specified single rotation axis.'),('No COM inertia because the second joint is prismatic','The second link still rotates with the first joint.')], 'A prismatic relative motion does not prevent inherited rigid-body angular motion.',steps=['For each link use omega=(0,0,thetadot1).','omegaᵀ I_C omega=Izz thetadot1².','Add both links’ spin energies.'],formulas=[ENERGY,RPE],kind='derivation',assumptions=[RP])
add('rp-second-speed','Radial and tangential velocity contributions',[442,443],'Why does the second COM speed squared equal d2dot²+d2² thetadot1², without a cross term?', [('Its radial and tangential velocity vectors are perpendicular','Their dot product vanishes when the velocity norm is squared.'),('The radial velocity is assumed to be zero','The source retains a nonzero d2dot term.'),('The angular velocity is assumed constant','A constant angular rate would not itself remove a cross term between nonorthogonal directions.'),('Kinetic energy is defined using the sum of speed magnitudes rather than a squared vector norm','The vector norm, not an arbitrary scalar sum, determines kinetic energy.')], 'Polar COM motion has one outward component and one perpendicular tangential component.',steps=['Write vC2=d2dot e_r+d2 thetadot1 e_t.','Use e_r·e_t=0 and unit vector norms.','vC2·vC2=d2dot²+d2² thetadot1².'],formulas=[RPE],kind='derivation',assumptions=[RP])
add('rp-kinetic-coefficient','Building the rotational energy coefficient',[443],'Which expression is A(d2), the coefficient of thetadot1² in 2K when d2dot=0?', [('m1 l1²+Izz1+Izz2+m2 d2²','Both COM translations and both COM spin inertias contribute.'),('m1 l1²+Izz1+m2 d2²','This omits link2 COM spin inertia.'),('Izz1+Izz2','This omits both COM translations around the first joint.'),('m1 l1²+Izz1+Izz2−m2 d2²','The second mass’s kinetic contribution is positive, not negative.')], 'A combines all motion caused by theta1, including the translating COM of the prismatic link.',formulas=[RPE],assumptions=[RP])
add('rp-kinetic-numerical','Computing both kinetic-energy contributions',[443],'Use m1=2 kg, l1=0.5 m, Izz1=0.2 kg·m², Izz2=0.3 kg·m², m2=3 kg, d2=0.4 m, thetadot1=2 rad/s and d2dot=0.5 m/s. What is K?', [('3.335 J','A=1.48 kg·m², rotational contribution 2.96 J and radial contribution 0.375 J.'),('2.96 J','This omits radial kinetic energy.'),('2.335 J','This omits both COM spin inertias, whose combined energy is 1 J.'),('6.67 J','This omits both factors of one-half.')], 'Do not omit COM spin or sliding translation when collecting the scalar system energy.',steps=['A=2×0.5²+0.2+0.3+3×0.4²=1.48 kg·m².','K_rotation=0.5×1.48×2²=2.96 J.','K_radial=0.5×3×0.5²=0.375 J.','K=3.335 J.'],formulas=[RPE],kind='numerical',assumptions=[RP])
add('rp-reference','Maximum extension is a constant energy datum',[444],'In U2=m2 g d2 sin(theta1)+m2 g d2max, what is partial U2/partial d2 when d2max is a fixed design limit?', [('m2 g sin(theta1)','The reference term is constant with respect to the instantaneous coordinate.'),('m2 g[sin(theta1)+1]','This incorrectly differentiates d2max as though it were d2.'),('Zero','The first term depends on the instantaneous radius d2.'),('m2 g cos(theta1)','That differentiates the angle dependence instead of the radius.')], 'The maximum-extension parameter sets the zero reference and is not a moving generalized coordinate.',steps=['Hold theta1 and fixed d2max constant in the partial derivative.','Differentiate m2 g d2 sin(theta1).','The derivative of m2 g d2max is zero.'],formulas=[RPE],kind='derivation',assumptions=[RP])
add('rp-minimum-reference','When the chosen potential minimum is zero',[443,444],'Assume 0≤d2≤d2max and the arm may point vertically downward. At which configuration does the stated total potential U attain zero?', [('theta1=−pi/2 and d2=d2max','Both link COMs attain the downward minima used by the reference constants.'),('theta1=0 and d2=0','The reference constants remain positive at that configuration.'),('theta1=pi/2 and d2=d2max','This is upward, giving the highest rather than lowest heights for that radius.'),('theta1=−pi/2 and every d2','U2=m2 g(d2max−d2), which is zero only at the maximum radius when m2 g>0.')], 'The reference constant uses the largest downward reach, so smaller extensions need not have zero potential even when pointing down.',steps=['At sin(theta1)=−1, U=m2 g(d2max−d2).','Under 0≤d2≤d2max this is nonnegative.','It vanishes at d2=d2max; each individual link minimum is then reached.'],formulas=[RPE],kind='derivation',assumptions=[RP,'g>0; the stated downward orientation and full extension are within the allowable joint range.'])
add('rp-derivative-vectors','Three derivative vectors in coordinate order',[444],'For q=(theta1,d2), which pair gives partial K/partial q and partial U/partial q?', [('(0,m2 d2 thetadot1²)ᵀ and (g(m1 l1+m2 d2)cos(theta1),m2 g sin(theta1))ᵀ','K has only d2 coordinate dependence; U differentiates in both coordinates.'),('(m2 d2 thetadot1²,0)ᵀ and the same stated U vector','This swaps the coordinate order in K_q.'),('(0,2m2 d2 thetadot1²)ᵀ and the same stated U vector','The one-half in K cancels the derivative factor two.'),('(0,m2 d2 thetadot1²)ᵀ and (−g(m1 l1+m2 d2)cos(theta1),m2 g cos(theta1))ᵀ','Both gravity derivatives are incorrect for the stated U.')], 'Differentiate with respect to the coordinates while holding generalized velocities independent.',steps=['K_theta1=0.','K_d2=0.5×2m2 d2 thetadot1²=m2 d2 thetadot1².','U_theta1=g(m1 l1+m2 d2)cos(theta1).','U_d2=m2 g sin(theta1).'],formulas=[RPE],kind='derivation',assumptions=[RP])
add('rp-generalized-momenta','Velocity derivatives of the RP kinetic energy',[444],'Which vector is partial K/partial qdot for qdot=(thetadot1,d2dot)?', [('(A thetadot1,m2 d2dot)ᵀ','Differentiate each quadratic velocity term.'),('(A thetaddot1,m2 d2ddot)ᵀ','Those are parts of its later time derivative, not the velocity derivative itself.'),('(A thetadot1²,m2 d2dot²)ᵀ','Differentiating a quadratic lowers the power by one.'),('(A/2 thetadot1,m2/2 d2dot)ᵀ','The derivative factor two cancels the one-half.')], 'The velocity derivative gives generalized momentum; its subsequent time derivative produces inertial effort.',steps=['partial(0.5 A thetadot1²)/partial thetadot1=A thetadot1.','partial(0.5 m2 d2dot²)/partial d2dot=m2 d2dot.'],formulas=[RPE],kind='derivation',assumptions=[RP])
add('rp-product-rule','The product-rule origin of Coriolis coupling',[444,445],'Since A=m1 l1²+Izz1+Izz2+m2 d2², what is d/dt(A thetadot1)?', [('A thetaddot1+2m2 d2 d2dot thetadot1','A changes as the prismatic COM radius changes.'),('A thetaddot1 only','This incorrectly holds the configuration-dependent A constant.'),('A thetaddot1+m2 d2 d2dot thetadot1','This misses the factor two from differentiating d2².'),('A thetaddot1+2m2 d2 d2ddot thetadot1','The first time derivative of d2 is d2dot, not d2ddot.')], 'A diagonal mass matrix may still depend on configuration, so differentiating generalized momentum produces coupling.',steps=['dA/dt=2m2 d2 d2dot.','Apply the product rule: d(A thetadot1)/dt=A thetaddot1+(dA/dt)thetadot1.'],formulas=[RPE,RPD],kind='derivation',assumptions=[RP])
add('rp-radial-effort','Sign of the radial squared-rate term',[445,446],'Which radial actuator-force equation follows from the Euler–Lagrange substitution?', [('F2=m2 d2ddot−m2 d2 thetadot1²+m2 g sin(theta1)','The coordinate derivative K_d2 is subtracted and U_d2 is added.'),('F2=m2 d2ddot+m2 d2 thetadot1²+m2 g sin(theta1)','This reverses the sign of −K_d2.'),('F2=m2 d2ddot−2m2 d2 thetadot1²+m2 g sin(theta1)','The kinetic derivative has no remaining factor two.'),('F2=m2 d2ddot−m2 d2 thetadot1²+m2 g cos(theta1)','This uses the torque gravity factor in the radial-force equation.')], 'The negative radial rate term is required for inward centripetal acceleration at fixed radius, with positive actuator force defined outward.',steps=['d/dt(K_d2dot)=m2 d2ddot.','Subtract K_d2=m2 d2 thetadot1².','Add U_d2=m2 g sin(theta1).'],formulas=[RPD],kind='derivation',assumptions=[RP])
add('rp-mass-typo','Reconciling the unclear lower mass-matrix print',[443,446],'The lower standalone M display has an unclear underscore-like symbol before m2 d2². Which M11 follows consistently from K and the clear upper torque equation?', [('m1 l1²+Izz1+Izz2+m2 d2²','It is the positive coefficient of thetadot1² in 2K.'),('m1 l1²+Izz1+Izz2−m2 d2²','That contradicts the positive second-COM kinetic contribution and the upper equation.'),('m1 l1²+Izz1+Izz2','This discards the configuration-dependent second-COM translation.'),('m2 d2² only','This discards the first link and both COM spin energies.')], 'Use mutually consistent source premises and retain the printing issue rather than treating the unclear symbol as a new physical model.',steps=['Read K=0.5 A thetadot1²+0.5m2 d2dot² on page443.','Differentiate twice with respect to thetadot1 to obtain M11=A.','Check the same plus sign in the upper scalar torque equation on page446.'],formulas=[RPE,RPM],kind='derivation',assumptions=[RP])
add('rp-diagonal-not-decoupled','A diagonal M does not eliminate all coupling',[446],'M=diag(A(d2),m2) is diagonal in the RP coordinates. Which conclusion is justified?', [('There are no cross-acceleration terms in this coordinate representation, but velocity and configuration coupling remain','A depends on d2 and the two velocity-product terms are nonzero in general.'),('The revolute and prismatic dynamics are completely independent','The explicit terms 2m2 d2 thetadot1 d2dot and −m2 d2 thetadot1² refute this.'),('All Coriolis and centrifugal terms must be zero','Diagonality of M does not imply constant M.'),('Gravity can act on only one joint','Both entries of G can be nonzero.')], 'Acceleration coupling, velocity coupling and gravity dependence are distinct features of a dynamic model.',formulas=[RPM],assumptions=[RP])
add('rp-mixed-dimensions','Units of a mixed-coordinate mass matrix',[438,446],'For q=(theta1,d2), what are the units of M11 and M22 in the displayed diagonal M?', [('M11: kg·m²; M22: kg','They multiply angular and linear acceleration to produce torque and force.'),('Both kg·m²','This treats the prismatic acceleration as angular acceleration.'),('Both kg','This omits the moment-arm units for rotational inertia.'),('M11: kg; M22: kg·m²','This reverses the coordinate roles.')], 'A mixed-coordinate matrix need not have identical units in all entries; each row and column has a physical pairing.',formulas=[RPM],kind='match',assumptions=[RP])
add('rp-numerical-efforts','Computing torque and force together',[446],'Use m1=2 kg, l1=0.5 m, Izz1=0.2 kg·m², Izz2=0.3 kg·m², m2=3 kg, d2=0.4 m, theta1=0, thetadot1=2 rad/s, d2dot=0.5 m/s, thetaddot1=1 rad/s², d2ddot=−0.2 m/s² and g=10 m/s². What is (tau1,F2)?', [('(25.88 N·m, −5.4 N)','The first components are 1.48+2.4+22; the second is −0.6−4.8+0.'),('(24.68 N·m, −5.4 N)','This halves the product-rule torque from 2.4 to 1.2.'),('(25.88 N·m, 4.2 N)','This reverses the centripetal-force sign: −0.6+4.8.'),('(3.88 N·m, −5.4 N)','This omits the 22 N·m gravity-compensation torque.')], 'Evaluate M qddot, V and G independently, remembering that the second generalized effort is a force.',steps=['A=2×0.5²+0.2+0.3+3×0.4²=1.48 kg·m².','tau1=1.48×1+2×3×0.4×2×0.5+(2×0.5+3×0.4)×10=25.88 N·m.','F2=3×(−0.2)−3×0.4×2²+3×10×sin0=−5.4 N.'],formulas=[RPD,RPM],kind='numerical',difficulty='medium',assumptions=[RP])

add('rp-rate-signs','Reversing only the revolute rate',[446],'At fixed q, qddot and nonzero d2dot, reverse only thetadot1. Which statements about V are correct? Select all that apply.', [('The first velocity-product component reverses sign','It is proportional to thetadot1 times unchanged d2dot.'),('The second velocity-product component is unchanged','It depends on thetadot1².'),('Both velocity-product components reverse sign','A squared angular rate is even under reversal.'),('The gravity vector changes sign','G depends on position, not the rate direction.')], 'A Coriolis product responds to reversing one of its factors, whereas the centrifugal squared-rate term does not.',correct=(0,1),formulas=[RPM],kind='multiple_select',assumptions=[RP])
add('rp-fixed-radius','Centripetal effort at fixed radial coordinate',[446],'Set g=0, d2dot=d2ddot=0, m2=2 kg, d2=0.5 m and thetadot1=3 rad/s. What radial actuator force is needed?', [('−9 N, inward','F2=−m2 d2 thetadot1²=−2×0.5×9.'),('Zero','Fixed radius does not mean zero radial acceleration in Cartesian space.'),('+9 N, outward','This reverses the required centripetal direction.'),('−3 N','This uses the angular rate instead of its square.')], 'Holding a constant radius during rotation requires an inward force even though the generalized radial acceleration is zero.',steps=['The radial acceleration term m2 d2ddot and gravity term vanish.','F2=−m2 d2 thetadot1².','Substitute to obtain −9 N.'],formulas=[RPD],kind='numerical',assumptions=[RP])
add('rp-static-gravity','Static horizontal and vertical support',[446],'With all joint rates and accelerations zero, compare theta1=0 with theta1=pi/2. Which pair of generalized gravity efforts is correct?', [('At 0: (g(m1 l1+m2 d2),0); at pi/2: (0,m2 g)','Horizontal gravity creates revolute moment; vertical gravity requires radial support.'),('At 0: (0,m2 g); at pi/2: (g(m1 l1+m2 d2),0)','This interchanges sine and cosine roles.'),('Both efforts vanish in either configuration because the robot is stationary','Static support can require nonzero actuator effort.'),('At pi/2 both efforts vanish because the revolute moment arm is zero','Zero revolute moment does not remove the prismatic weight load.')], 'The same gravitational load projects differently onto rotational and translational joint freedoms.',formulas=[RPM],kind='scenario',assumptions=[RP])
add('rp-cyclic-momentum','Angular momentum with zero gravity and input torque',[443,445,446],'Set g=0 and tau1=0, but permit the prismatic actuator to change d2. Which quantity is conserved by the first equation?', [('A(d2) thetadot1','Its total time derivative is exactly the first unforced equation.'),('thetadot1 itself for every changing d2','A changes with extension, so the rate generally changes.'),('A(d2) thetadot1²','That resembles twice the rotational kinetic energy, not generalized momentum.'),('d2 thetadot1','That omits the squared radius and the constant inertia contributions.')], 'No applied torque about theta1 conserves its generalized momentum, even while a radial actuator changes the rotational inertia.',steps=['With g=tau1=0, A thetaddot1+2m2 d2 d2dot thetadot1=0.','Recognize dA/dt=2m2 d2 d2dot.','Thus d(A thetadot1)/dt=0.'],formulas=[RPE,RPD],kind='derivation',difficulty='medium',assumptions=[RP,'g=0 and no applied revolute torque; the prismatic actuator may do work.'])
add('rp-cyclic-momentum','Angular momentum with zero gravity and input torque',[443,445,446],'Let m1=1 kg, l1=1 m, Izz1=Izz2=0.5 kg·m² and m2=2 kg. With g=tau1=0, a radial actuator changes d2 from 0.5 m to 1 m. If the initial angular rate is 4 rad/s, what is the final angular rate?', [('2.5 rad/s','A changes from 2.5 to 4, so conserved A thetadot1=10 gives 10/4.'),('4 rad/s','This assumes a constant angular rate despite changing inertia.'),('6.4 rad/s','This multiplies the rate by A_final/A_initial rather than its reciprocal.'),('1 rad/s','This applies only a squared-radius scaling and omits the constant inertia 2 kg·m².')], 'The radial actuator may change total energy, but in this zero-gravity, zero-revolute-torque model it does not change the theta1 generalized momentum.',steps=['The constant inertia contribution is 1×1²+0.5+0.5=2 kg·m².','A_initial=2+2×0.5²=2.5 kg·m² and A_final=2+2×1²=4 kg·m².','Conserve A thetadot1: p=2.5×4=10 kg·m²/s.','Final angular rate=10/4=2.5 rad/s.'],formulas=[RPE,RPD],kind='numerical',difficulty='hard',assumptions=[RP,'g=0 and no revolute actuator torque throughout; radial actuator work is allowed.'])
add('rp-energy-identity','A consistency check on velocity-product efforts',[443,446],'For qdot=(w,v)=(thetadot1,d2dot), the source gives V=(2m2 d2 wv,−m2 d2 w²). Which identity is consistent with K=1/2 qdotᵀM qdot?', [('qdotᵀV=m2 d2 w²v=1/2 qdotᵀMdot qdot','The two mixed-effort power terms partly cancel, leaving the configuration-rate energy term.'),('qdotᵀV=0 for all w,v because inertial forces never contribute this term','M varies with d2, so the kinetic-energy derivative contains Mdot.'),('qdotᵀV=2m2 d2 w²v','This omits the negative radial-effort contribution.'),('qdotᵀV=−m2 d2 w²v','This omits the positive revolute-effort contribution.')], 'The velocity-product vector supplies exactly the kinetic-energy change caused by the changing mass matrix. This is a check on both the factor two and the radial minus sign.',steps=['qdotᵀV=w(2m2 d2 wv)+v(−m2 d2 w²)=m2 d2 w²v.','Only M11 changes: Mdot11=2m2 d2 v.','1/2 qdotᵀMdot qdot=1/2 w²(2m2 d2 v)=m2 d2 w²v.'],formulas=[RPM,form('qdotᵀV=1/2 qdotᵀMdot qdot',{'qdot':'[thetadot1,d2dot]ᵀ','V':'velocity-product generalized efforts','Mdot':'total time derivative of M(q)'},{'qdot components':'rad/s, m/s','V components':'N·m, N','both scalar sides':'W'},['Identity derived for the stated RP model.'])],kind='derivation',difficulty='hard',assumptions=[RP])
add('rp-power-pairing','Actuator power for mixed joints',[438,446],'For the RP generalized efforts, which expression gives the instantaneous applied actuator power?', [('tau1 thetadot1+F2 d2dot','Torque pairs with angular rate and force with linear rate.'),('tau1 d2dot+F2 thetadot1','This swaps the coordinate/effort pairs and their units.'),('tau1 thetaddot1+F2 d2ddot','Acceleration is not the power-conjugate quantity.'),('tau1+F2','The two efforts have different units and are not powers by themselves.')], 'The generalized-effort notation groups distinct physical actuators without changing their correct work and power pairings.',formulas=[RPM,form('P=Qᵀqdot=tau1 thetadot1+F2 d2dot',{'P':'applied mechanical power','Q':'[tau1,F2]ᵀ','qdot':'[thetadot1,d2dot]ᵀ','tau1':'revolute torque','F2':'prismatic force','thetadot1':'angular rate','d2dot':'radial speed'},{'P':'W','tau1':'N·m','F2':'N','thetadot1':'rad/s','d2dot':'m/s'})],assumptions=[RP])
add('example-sign-contrast','Why the examples have opposite potential signs',[439,443,444],'The single-joint example contains −mgl sin(theta), while the RP gravitational term is +g(m1 l1+m2 d2)sin(theta1). Which interpretation is consistent with their stated coordinate conventions?', [('The single-joint angle increases downward; the RP height convention increases upward','Both use potential increasing with physical height, expressed in different coordinates.'),('Gravity changes physical direction between the examples','Both diagrams show downward gravity.'),('Lagrange requires a negative gravitational potential for one DOF and positive for two DOFs','The number of coordinates does not determine the sign convention.'),('One must replace both signs by plus before differentiating','That would silently change the single-joint model.')], 'Potential signs follow coordinate definitions, not the number of joints or the choice of dynamics method.',kind='scenario',assumptions=[SINGLE,RP])
add('summary-symbol-overload','Two different uses of the symbol V',[434,446,447],'The summary writes L=K−V and also tau=M qddot+V(q,qdot)+G(q). What must be distinguished?', [('The first V is scalar potential energy; the second V is a velocity-product generalized-effort vector','Their roles, shapes and units differ despite the reused letter.'),('Both V symbols are the same scalar energy and can be interchanged','The dynamic decomposition requires an effort vector.'),('The first V is velocity and the second is potential energy','That conflicts with both source expressions.'),('V(q,qdot) must be zero whenever potential energy is chosen zero at a reference','An energy datum has no effect on the velocity-product vector.')], 'Rename the scalar U and retain V_velocity for the vector when writing a clear combined formula.',formulas=[EL,RPM],kind='conceptual',memory='U is an energy; V_velocity is an effort vector.')
add('formulation-sequence','A source-consistent derivation workflow',[435,436,437,444,445],'Which workflow respects the dependencies of the energy derivation?', [('Choose independent coordinates and conventions → form total K and U → compute partial and total time derivatives → collect actuator equations','The energies and their dependence must be known before differentiating.'),('Choose M by its desired diagonal appearance → infer K afterward → discard unmatched velocity terms','The matrix and velocity terms must follow from the same energies, not an aesthetic choice.'),('Differentiate only U → declare all inertial efforts zero → recover K from gravity','K contributes inertial and velocity-product efforts independently of U.'),('Set every generalized velocity to zero before differentiation → use the result for arbitrary motion','This deletes terms needed in the general dynamic equations.')], 'Partial derivatives treat coordinates and velocities as independent arguments; the later total time derivative follows the actual motion.',steps=['Identify q and the physical coordinate/effort conventions.','Compute each link’s translation/spin energy and potential, then sum.','Evaluate K_qdot, K_q and U_q.','Take d(K_qdot)/dt with the full product/chain rule.','Assemble and simplify Q=d(K_qdot)/dt−K_q+U_q.'],formulas=[EL],kind='sequence')
# In-batch prerequisites support targeted revision without claiming cross-lecture completeness.
links={'single-equation':['single-angle','lagrange-operator','potential-sign'],'single-numerical':['single-equation','spring-angle-units'],'rp-derivative-vectors':['rp-kinetic-coefficient','rp-reference'],'rp-product-rule':['rp-generalized-momenta'],'rp-numerical-efforts':['rp-product-rule','rp-radial-effort','rp-mixed-dimensions'],'rp-cyclic-momentum':['rp-product-rule'],'rp-energy-identity':['rp-product-rule','rp-radial-effort'],'summary-symbol-overload':['energy-versus-lagrangian']}
for key,req in links.items():
 cid=f'{BATCH}-C-{key}';ids=[f'{BATCH}-C-{r}' for r in req];C[cid]['prerequisiteConceptIds']=ids
 for q in Q:
  if cid in q['conceptIds']:q['solution']['prerequisiteConceptIds']=ids
save(frozen=True)
